-- Catálogo online: instalação inicial idempotente. Os temas são dados, não código.
CREATE OR REPLACE FUNCTION public.fila_temas_catalogo(p_codigo text, p_token text DEFAULT NULL, p_coord text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
AS $function$
DECLARE dados jsonb;
BEGIN
  PERFORM public.fila_ator(p_codigo,p_token,p_coord,false);
  SELECT valor::jsonb INTO dados FROM public.fila_config WHERE chave='temas_catalogo_v1';
  IF dados IS NULL THEN RAISE EXCEPTION 'Catálogo indisponível'; END IF;
  RETURN dados;
END $function$;
REVOKE ALL ON FUNCTION public.fila_temas_catalogo(text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fila_temas_catalogo(text,text,text) TO anon, authenticated, service_role;

