INSERT INTO public.fila_config(chave,valor)
VALUES('temas_catalogo_revisao','1')
ON CONFLICT(chave) DO NOTHING;

-- A fila carrega somente a revisão; o catálogo completo tem uma consulta própria.
DO $patch$
DECLARE antes text; depois text;
BEGIN
  antes := pg_get_functiondef('public.fila_estado(text,text,text)'::regprocedure);
  IF position($ja$chave NOT IN ('codigo','codigo_coord','temas_catalogo_v1')$ja$ IN antes)>0 THEN RETURN; END IF;
  depois := replace(antes,
    $original$chave NOT IN ('codigo','codigo_coord')$original$,
    $novo$chave NOT IN ('codigo','codigo_coord','temas_catalogo_v1')$novo$);
  IF depois=antes THEN RAISE EXCEPTION 'A função da fila mudou. Revise antes de aplicar.'; END IF;
  EXECUTE depois;
END $patch$;
